// Ports design-system/graphite/dist into this package:
//   - components/bundle.js  -> src/components/<Name>.ts (one module per component, typed with the public props)
//   - components/index.d.ts -> types/index.d.ts (public API, verbatim minus the window.Graphite global)
//   - tokens.css, components/bundle.css, tokens.json -> styles/, tokens.json (verbatim)
// The implementation is kept 1:1 with the reference bundle so the DOM and class names match bundle.css.
// Re-run after the DS changes: `pnpm graphite:port`.
import { readFileSync, writeFileSync, mkdirSync, rmSync, copyFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as acorn from 'acorn';
import * as walk from 'acorn-walk';

const here = dirname(fileURLToPath(import.meta.url));
const pkg = join(here, '..');
const dist = join(pkg, '../../design-system/graphite/dist');

const bundle = readFileSync(join(dist, 'components/bundle.js'), 'utf8');
const dts = readFileSync(join(dist, 'components/index.d.ts'), 'utf8');

// ---- public API (types) -------------------------------------------------------------
const header = (src) => `// Generated by scripts/port-bundle.mjs from design-system/graphite/dist/${src}. Do not edit by hand.\n`;
const dtsOut = dts.replace(/\ndeclare global \{[\s\S]*$/, '\n');
if (dtsOut === dts) throw new Error('index.d.ts: window.Graphite global block not found');
mkdirSync(join(pkg, 'types'), { recursive: true });
writeFileSync(join(pkg, 'types/index.d.ts'), header('components/index.d.ts') + dtsOut);

const propTypes = new Set([...dts.matchAll(/export (?:interface|type) (\w+)/g)].map((m) => m[1]));
const genericProps = new Set(['TableProps', 'DataTableProps']);

// ---- styles -----------------------------------------------------------------------
mkdirSync(join(pkg, 'styles'), { recursive: true });
copyFileSync(join(dist, 'tokens.css'), join(pkg, 'styles/tokens.css'));
copyFileSync(join(dist, 'components/bundle.css'), join(pkg, 'styles/components.css'));
copyFileSync(join(dist, 'tokens.json'), join(pkg, 'tokens.json'));

// ---- implementation ---------------------------------------------------------------
const meta = JSON.parse(bundle.match(/\/\* @ds-bundle: (\{.*?\}) \*\//)[1]);
const PUBLIC = new Set([...meta.components.map((c) => c.name), 'Icon', 'Logo', 'Checkbox', 'Radio', 'Toggle']);
const RUNTIME = new Set(['React', 'h', 'useState', 'useEffect', 'useRef', 'useId', 'useCallback']);

const start = bundle.indexOf('(function(){') + '(function(){'.length;
const end = bundle.lastIndexOf('})();');
const body = bundle.slice(start, end);
const ast = acorn.parse(body, { ecmaVersion: 2020, sourceType: 'script', ranges: true });

function declared(stmt) {
  if (stmt.type === 'FunctionDeclaration') return [stmt.id.name];
  if (stmt.type === 'VariableDeclaration') return stmt.declarations.map((d) => d.id.name);
  return [];
}

function referenced(stmt) {
  const names = new Set();
  walk.fullAncestor(stmt, (node, _state, ancestors) => {
    if (node.type !== 'Identifier') return;
    const parent = ancestors[ancestors.length - 2];
    if (parent && parent.type === 'MemberExpression' && parent.property === node && !parent.computed) return;
    if (parent && parent.type === 'Property' && parent.key === node && !parent.computed && !parent.shorthand) return;
    names.add(node.name);
  });
  return names;
}

// Group statements into modules. Helpers attach to the next component-declaring statement.
const modules = new Map(); // file -> { stmts: [], names: Set }
const owner = new Map(); // top-level name -> file
let pending = [];
function add(file, stmts) {
  if (!modules.has(file)) modules.set(file, { stmts: [], names: new Set() });
  const m = modules.get(file);
  for (const s of stmts) {
    m.stmts.push(s);
    for (const n of declared(s)) { m.names.add(n); owner.set(n, file); }
  }
}
for (const stmt of ast.body) {
  const names = declared(stmt);
  if (stmt.type === 'ExpressionStatement') {
    const src = body.slice(stmt.start, stmt.end);
    if (src.startsWith('window.Graphite=')) continue;
    throw new Error('Unexpected top-level expression: ' + src.slice(0, 80));
  }
  if (names.length && names.every((n) => RUNTIME.has(n))) continue;
  if (names.includes('ICONS')) { add('icons', [stmt]); continue; }
  if (names.includes('cx') || names.includes('omit')) { add('utils', [stmt]); continue; }
  const comp = names.find((n) => PUBLIC.has(n));
  if (comp) { add('components/' + comp, [...pending, stmt]); pending = []; }
  else pending.push(stmt);
}
if (pending.length) throw new Error('Trailing helpers without a component: ' + pending.map(declared).join(','));

// Emit.
rmSync(join(pkg, 'src/components'), { recursive: true, force: true });
mkdirSync(join(pkg, 'src/components'), { recursive: true });

writeFileSync(join(pkg, 'src/runtime.ts'), header('components/bundle.js') + `// The ported implementation is untyped ES5, so React is exposed loosely here.
// The public API is typed strictly by types/index.d.ts (what consumers see).
import * as ReactNS from 'react';
export const React: any = ReactNS;
export const h: (type: any, props?: any, ...children: any[]) => ReactNS.ReactElement = ReactNS.createElement as any;
export const useState: (initial?: any) => [any, (next: any) => void] = ReactNS.useState as any;
export const useEffect: (effect: () => any, deps?: any[]) => void = ReactNS.useEffect as any;
export const useRef: (initial?: any) => { current: any } = ReactNS.useRef as any;
export const useId: () => string = ReactNS.useId;
export const useCallback: (fn: any, deps: any[]) => any = ReactNS.useCallback as any;
`);
writeFileSync(join(pkg, 'src/internal.d.ts'), header('components/bundle.js') + `// Internal only (not referenced by types/index.d.ts): the reference bundle calls focus() on
// elements returned by querySelectorAll / document.activeElement.
interface Element { focus(options?: FocusOptions): void }
`);

function rel(from, to) {
  const a = from.split('/').slice(0, -1);
  const b = to.split('/');
  let i = 0;
  while (i < a.length && a[i] === b[i]) i++;
  const up = a.slice(i).map(() => '..');
  const path = [...up, ...b.slice(i)].join('/');
  return path.startsWith('.') ? path : './' + path;
}

for (const [file, mod] of modules) {
  const refs = new Set();
  for (const s of mod.stmts) for (const r of referenced(s)) refs.add(r);
  const runtime = [...RUNTIME].filter((n) => refs.has(n));
  const imports = new Map();
  for (const r of refs) {
    const f = owner.get(r);
    if (!f || f === file) continue;
    if (!imports.has(f)) imports.set(f, new Set());
    imports.get(f).add(r);
  }
  const types = new Set();
  const code = mod.stmts.map((s) => {
    let src = body.slice(s.start, s.end);
    // Variadic helpers read `arguments`; declare a rest parameter so TypeScript accepts the call sites.
    if (s.type === 'FunctionDeclaration' && s.params.length === 0 && /\barguments\b/.test(src)) {
      src = src.replace(/^function (\w+)\(\)/, 'function $1(..._args: any[])');
    }
    if (s.type === 'FunctionDeclaration' && PUBLIC.has(s.id.name)) {
      const t = s.id.name + 'Props';
      if (propTypes.has(t) && s.params.length === 1 && s.params[0].type === 'Identifier') {
        const p = s.params[0];
        const at = p.end - s.start;
        const typed = genericProps.has(t) ? `${t}<any>` : t;
        src = src.slice(0, at) + ': ' + typed + src.slice(at);
        types.add(t);
      }
    }
    return 'export ' + src;
  }).join('\n');

  const lines = [];
  if (file.startsWith('components/')) lines.push("'use client';");
  lines.push(header('components/bundle.js').trimEnd());
  if (runtime.length) lines.push(`import { ${runtime.join(', ')} } from '${rel(file, 'runtime')}';`);
  if (types.size) lines.push(`import type { ${[...types].sort().join(', ')} } from '${rel(file, '../types/index')}';`);
  for (const [f, names] of [...imports].sort()) lines.push(`import { ${[...names].sort().join(', ')} } from '${rel(file, f)}';`);
  lines.push('', code, '');
  writeFileSync(join(pkg, 'src', file + '.ts'), lines.join('\n'));
}

// Barrel: only the public components, in bundle order.
const order = [...meta.components.map((c) => c.name)];
for (const n of ['Icon', 'Logo', 'Checkbox', 'Radio', 'Toggle']) if (!order.includes(n)) order.push(n);
const barrel = [header('components/bundle.js').trimEnd(), "'use client';"];
const byFile = new Map();
for (const n of order) {
  const f = owner.get(n);
  if (!f) throw new Error('Component not found in bundle: ' + n);
  if (!byFile.has(f)) byFile.set(f, []);
  byFile.get(f).push(n);
}
for (const [f, names] of byFile) barrel.push(`export { ${names.join(', ')} } from './${f}';`);
barrel.push("export type * from '../types/index';", '');
// 'use client' must be the first statement.
writeFileSync(join(pkg, 'src/index.ts'), ["'use client';", ...barrel.filter((l) => l !== "'use client';")].join('\n'));

console.log(`Ported ${order.length} public components into ${modules.size} modules.`);
await import('./inject-i18n.mjs');
